settings.custom_css:
selector {color:#241b14; font-family:"Hind Siliguri",sans-serif; min-width:0;}
selector *, selector *::before, selector *::after {box-sizing:border-box;}
selector .woocommerce form .form-row input.input-text, selector .woocommerce form .form-row textarea, selector .woocommerce form .form-row select {width:100%; max-width:100%; border:2px solid #244b21; border-radius:3px; background:#fff; min-height:46px; padding:10px; color:#261b15; font:inherit;}
selector .woocommerce #customer_details, selector .woocommerce #order_review, selector .woocommerce #order_review_heading {width:100%; float:none; clear:both;}
selector .woocommerce .col2-set .col-1, selector .woocommerce .col2-set .col-2 {float:none; width:100%;}
selector .woocommerce table.shop_table {width:100%; border-collapse:collapse; font-size:15px;}
selector .woocommerce table.shop_table th, selector .woocommerce table.shop_table td {padding:12px 6px; overflow-wrap:anywhere;}
selector .woocommerce ul#shipping_method {padding-left:0; list-style:none;}
selector .woocommerce ul#shipping_method li {padding:10px; border:1px solid #ddd; margin:0;}
selector .woocommerce #payment {background:#f7f7f7; border-radius:4px;}
selector .woocommerce #payment div.payment_box {background:#eaeaea; color:#333;}
selector .woocommerce #place_order {width:100%; float:none; white-space:normal; background:#c90050; color:#fff; border:1px solid #ff4b1b; border-radius:3px; padding:17px 14px; font:700 17px "Hind Siliguri",sans-serif; cursor:pointer;}
selector .woocommerce a {color:#df4619;}
selector .woocommerce input:focus-visible, selector .woocommerce button:focus-visible {outline:3px solid #ff9f08; outline-offset:2px;}
@media(max-width:767px) {selector .woocommerce .form-row {float:none; width:100%;} selector .woocommerce table.shop_table {font-size:14px;} selector .woocommerce .woocommerce-checkout-review-order {min-width:0;}}
